const state = { stage: 'reference', rightTab: 'reference', selectedIssue: 'joint', confirmed: false, history: [] };
const $ = (id) => document.getElementById(id);
const toast = (message) => { const el = $('toast'); el.textContent = message; el.classList.remove('hidden'); el.classList.add('show'); setTimeout(() => el.classList.add('hidden'), 2200); };
const renderRightTab = (tab) => { document.querySelectorAll('.right-tab').forEach((button) => button.classList.toggle('active', button.dataset.rightTab === tab)); document.querySelectorAll('.right-context').forEach((panel) => panel.classList.toggle('hidden', panel.dataset.rightContent !== tab)); };
const setRightTab = (tab) => { state.rightTab = tab; history.pushState({ tab }, '', `#${tab}`); renderRightTab(tab); };
const renderStage = () => { $('reference-state').classList.toggle('hidden', state.stage !== 'reference'); $('model-state').classList.toggle('hidden', state.stage !== 'model'); $('airport-state').classList.toggle('hidden', state.stage !== 'airport'); $('stage-eyebrow').textContent = state.stage === 'reference' ? '参考已导入 · 结构候选未确认' : state.stage === 'model' ? (state.confirmed ? '设计已确认 · 可生成加工包' : '结构候选 · v3 draft') : 'Airport 预览 · v3'; $('stage-title').textContent = state.stage === 'reference' ? '先把喜欢的椅子看懂' : state.stage === 'model' ? '围绕模型继续设计' : '模型已进入 Airport'; $('commit-button').classList.toggle('locked', !state.confirmed || state.stage === 'airport'); $('commit-button').textContent = state.stage === 'airport' ? '已提交' : '提交 Airport'; $('save-state').textContent = state.confirmed ? '已保存 · v4' : '已保存 · v3'; };
const renderTasks = () => { document.querySelectorAll('.task-card').forEach((el) => el.classList.toggle('current', el.dataset.task === 'joint' && state.selectedIssue === 'joint')); };
const render = () => { renderStage(); renderTasks(); renderRightTab(state.rightTab); };
document.querySelectorAll('.right-tab').forEach((button) => button.addEventListener('click', () => setRightTab(button.dataset.rightTab)));
document.querySelectorAll('[data-panel]').forEach((el) => el.addEventListener('click', () => setRightTab(el.dataset.panel === 'design' ? 'layers' : el.dataset.panel)));
document.querySelectorAll('.task-card[data-task]').forEach((el) => el.addEventListener('click', (event) => { if (event.target.closest('button')) return; state.selectedIssue = el.dataset.task === 'joint' ? 'joint' : ''; document.querySelectorAll('.task-card').forEach((task) => task.classList.remove('expanded')); el.classList.add('expanded'); renderTasks(); toast(el.querySelector('strong').textContent); }));
document.querySelectorAll('[data-action="generate"]').forEach((el) => el.addEventListener('click', () => { state.stage = 'model'; render(); toast('已生成结构候选，等待确认'); }));
document.querySelectorAll('[data-action="confirm"]').forEach((el) => el.addEventListener('click', () => { state.confirmed = true; render(); toast('设计已确认，加工包已解锁'); }));
document.querySelectorAll('[data-action="apply-joint"]').forEach((el) => el.addEventListener('click', () => { const task = document.querySelector('[data-task="joint"]'); task.querySelector('.task-summary strong').textContent = '接合方式已确认'; task.querySelector('.task-summary small').textContent = '已完成 · 半搭接'; state.selectedIssue = ''; task.classList.remove('current'); task.classList.remove('expanded'); toast('已应用半搭接，下一项任务已准备好'); }));
document.querySelectorAll('[data-action="select-joint"]').forEach((el) => el.addEventListener('click', () => toast('原型中保留接合候选选择位置')));
document.querySelectorAll('[data-action="commit"]').forEach((el) => el.addEventListener('click', () => { if (!state.confirmed) { toast('请先确认设计'); return; } state.stage = 'airport'; render(); toast('已提交 Airport 预览'); }));
document.querySelectorAll('[data-action="back-model"]').forEach((el) => el.addEventListener('click', () => { state.stage = 'model'; render(); }));
document.querySelectorAll('[data-action="close-panel"]').forEach((el) => el.addEventListener('click', () => { document.querySelector('.right-panel').classList.toggle('closed'); }));
document.querySelectorAll('[data-action="export"], [data-action="focus-package"]').forEach((el) => el.addEventListener('click', () => { setRightTab('lists'); toast(state.confirmed ? '加工包已准备好下载' : '确认设计后才能导出加工包'); }));
document.querySelectorAll('[data-action="focus-reference"]').forEach((el) => el.addEventListener('click', () => setRightTab('reference')));
document.querySelectorAll('[data-action="focus-joint"]').forEach((el) => el.addEventListener('click', () => { state.selectedIssue = 'joint'; renderTasks(); toast('已定位到当前任务'); }));
document.querySelectorAll('.viewport-tool').forEach((el) => el.addEventListener('click', () => { document.querySelectorAll('.viewport-tool').forEach((tool) => tool.classList.remove('active')); el.classList.add('active'); toast(`视口工具：${el.textContent}`); }));
document.querySelectorAll('[data-view]').forEach((el) => el.addEventListener('click', () => toast(`切换视图：${el.textContent}`)));
document.querySelectorAll('[data-command]').forEach((el) => el.addEventListener('click', () => { $('command-input').value = el.dataset.command; $('command-input').focus(); }));
$('command-input').addEventListener('keydown', (event) => { if (event.key === 'Enter') document.querySelector('[data-action="command"]').click(); });
document.querySelector('[data-action="command"]').addEventListener('click', () => { const value = $('command-input').value.trim(); if (!value) return; state.history.push(value); $('command-input').value = ''; toast(`AI 已收到：“${value}”`); state.selectedIssue = 'joint'; renderTasks(); });
window.addEventListener('popstate', (event) => { state.rightTab = event.state?.tab || 'reference'; render(); });
render();
